{
  "decision-schedule-laundry-with-solar-headroom": "WITH draws AS (SELECT start_hour, grid_room_kwh, price_cents, MAX(0, 2 - spare_solar_kwh) AS wash_grid, MAX(0, 3 - spare_solar_kwh) AS dry_grid FROM hour_offer) SELECT w.start_hour AS wash_hour, d.start_hour AS dry_hour, w.wash_grid * w.price_cents + d.dry_grid * d.price_cents AS cost_cents FROM draws AS w JOIN draws AS d ON d.start_hour BETWEEN w.start_hour + 1 AND w.start_hour + 2 WHERE w.wash_grid <= w.grid_room_kwh AND d.dry_grid <= d.grid_room_kwh ORDER BY cost_cents, wash_hour, dry_hour LIMIT 1",
  "decision-schedule-reset-checks-before-dispatch": "WITH plans(first_job, second_job, saved_packages, cost_cents) AS (SELECT job_code, NULL, saved_count, kit_cents FROM reset_job UNION ALL SELECT a.job_code, b.job_code, a.saved_count + b.saved_count, a.kit_cents + b.kit_cents FROM reset_job AS a JOIN reset_job AS b ON a.job_code < b.job_code AND (a.finish_min <= b.start_min OR b.finish_min <= a.start_min)) SELECT first_job, second_job, saved_packages, cost_cents FROM plans WHERE cost_cents <= 90 ORDER BY saved_packages DESC, cost_cents, first_job, second_job LIMIT 1",
  "decision-score-slip-print-order": "WITH qty(packs) AS (VALUES (0), (1), (2), (3), (4), (5), (6)), orders AS (SELECT nq.packs AS narrow_packs, wq.packs AS wide_packs, nq.packs * n.slips + wq.packs * w.slips AS total_slips, nq.packs * n.pack_cents + wq.packs * w.pack_cents + CASE WHEN nq.packs > 0 THEN n.setup_cents ELSE 0 END + CASE WHEN wq.packs > 0 THEN w.setup_cents ELSE 0 END AS cost_cents FROM pack_offer AS n JOIN qty AS nq ON nq.packs <= n.stock CROSS JOIN pack_offer AS w JOIN qty AS wq ON wq.packs <= w.stock WHERE n.format_id = 'narrow' AND w.format_id = 'wide') SELECT narrow_packs, wide_packs, total_slips, cost_cents FROM orders CROSS JOIN print_job WHERE total_slips BETWEEN need_slips AND capacity_slips ORDER BY cost_cents, total_slips, narrow_packs LIMIT 1",
  "decision-select-capped-bonus-offers-within-monthly-pool": "WITH RECURSIVE masks(bits) AS (VALUES (0) UNION ALL SELECT bits + 1 FROM masks WHERE bits < 127), plans AS (SELECT m.bits AS selected_bits, COALESCE(SUM(o.retained_count), 0) AS retained_total, COALESCE(SUM(MIN(o.earned_cents, o.ceiling_cents)), 0) AS payout_cents FROM masks AS m LEFT JOIN campaign_offers AS o ON (m.bits & o.offer_bit) <> 0 GROUP BY m.bits HAVING COALESCE(SUM(o.offer_bit), 0) = m.bits AND COUNT(o.offer_bit) = COUNT(DISTINCT o.catalog_id)) SELECT selected_bits, retained_total, payout_cents FROM plans CROSS JOIN bonus_pool WHERE payout_cents <= budget_cents ORDER BY retained_total DESC, payout_cents, selected_bits LIMIT 1"
}
